const menu=document.querySelector('.menu'),nav=document.querySelector('.site-header nav');menu?.addEventListener('click',()=>{const open=document.body.classList.toggle('nav-open');menu.setAttribute('aria-expanded',String(open));menu.setAttribute('aria-label',open?'Close menu':'Open menu')});nav?.querySelectorAll('a').forEach(a=>a.addEventListener('click',()=>document.body.classList.remove('nav-open')));document.querySelector('[data-copy]')?.addEventListener('click',async e=>{await navigator.clipboard.writeText(e.currentTarget.dataset.copy);e.currentTarget.textContent='Copied'});const cursor=document.querySelector('.cursor-note');document.querySelectorAll('.case-card,.decision-block').forEach(el=>{el.addEventListener('mouseenter',()=>document.body.classList.add('case-hover'));el.addEventListener('mouseleave',()=>document.body.classList.remove('case-hover'))});window.addEventListener('pointermove',e=>{if(cursor){cursor.style.left=e.clientX+'px';cursor.style.top=e.clientY+'px'}});
